im_bindings_slack_route_fields.value:
"im_bindings"."provider" = 'slack' or (
        "im_bindings"."slack_installation_id" is null and "im_bindings"."slack_route_kind" is null
      )

mcp_server_authorizations_bearer_has_cre.value:
"mcp_server_authorizations"."kind" <> 'bearer' or (
        "mcp_server_authorizations"."status" not in ('pending', 'active') or "mcp_server_authorizations"."ciphertext" is not null
      )

mcp_server_authorizations_oauth_shape.value:
"mcp_server_authorizations"."kind" <> 'oauth' or (
        "mcp_server_authorizations"."status" not in ('active', 'expired') or "mcp_server_authorizations"."ciphertext" is not null
      )

slack_installations_disabled_secret_shap.value:
"slack_installations"."status" <> 'disabled' or (
        "slack_installations"."encrypted_credential" is null and "slack_installations"."disabled_at" is not null
      )
